/**
 * @developstack/format：界面上的日期、数字、相对时间都从这里出。
 * 内部固定 zh-CN；缺值和无效值一律返回 EMPTY。
 */

/** 缺值占位：U+2014。入参为空或无效时，所有 format* 函数都返回它。 */
export const EMPTY = "—";

export type DateInput = Date | string | number | null | undefined;
export type NumberInput = number | bigint | string | null | undefined;
export type DateOptions = {
  /** IANA 时区，如 "Asia/Shanghai"。缺省用运行环境的时区。 */
  timeZone?: string;
};
export type RelativeOptions = DateOptions & {
  /** 参照时刻，缺省为当前时间。测试里传固定值。 */
  now?: Date | number;
};

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
/** 满这个天数就不再说「N天前」，改显示绝对日期。 */
const RELATIVE_LIMIT_DAYS = 30;

function toDate(value: DateInput): Date | null {
  if (value === null || value === undefined || value === "") return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isFinite(date.getTime()) ? date : null;
}

/** 2026/10/03 14:05（24 小时制，不含秒）。 */
export function formatDateTime(value: DateInput, options: DateOptions = {}): string {
  const date = toDate(value);
  if (!date) return EMPTY;
  return new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
    timeZone: options.timeZone,
  }).format(date);
}

/** 2026/10/03。 */
export function formatDate(value: DateInput, options: DateOptions = {}): string {
  const date = toDate(value);
  if (!date) return EMPTY;
  return new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    timeZone: options.timeZone,
  }).format(date);
}

/** 1,234.5。0 是有效值。 */
export function formatNumber(value: NumberInput, options?: Intl.NumberFormatOptions): string {
  if (value === null || value === undefined) return EMPTY;
  let n: number | bigint;
  if (typeof value === "string") {
    if (value.trim() === "") return EMPTY;
    n = Number(value);
  } else {
    n = value;
  }
  if (typeof n === "number" && !Number.isFinite(n)) return EMPTY;
  return new Intl.NumberFormat("zh-CN", options).format(n);
}

/** 刚刚 / N分钟前 / N小时前 / N天前；将来用「后」；满 30 天退回 formatDate。 */
export function formatRelative(value: DateInput, options: RelativeOptions = {}): string {
  const date = toDate(value);
  if (!date) return EMPTY;
  const now = options.now === undefined ? Date.now() : new Date(options.now).getTime();
  const diff = date.getTime() - now; // 负数表示过去
  const abs = Math.abs(diff);
  if (abs < MINUTE) return "刚刚";
  if (abs >= RELATIVE_LIMIT_DAYS * DAY) return formatDate(date, options);
  const rtf = new Intl.RelativeTimeFormat("zh-CN", { numeric: "always" });
  const sign = Math.sign(diff);
  if (abs < HOUR) return rtf.format(sign * Math.floor(abs / MINUTE), "minute");
  if (abs < DAY) return rtf.format(sign * Math.floor(abs / HOUR), "hour");
  return rtf.format(sign * Math.floor(abs / DAY), "day");
}
